FUNCTION_BLOCK T01_AND_Gate
VAR_INPUT
    IN1 : BOOL;
    IN2 : BOOL;
END_VAR
VAR_OUTPUT
    OUT : BOOL;
END_VAR
OUT := IN1 AND IN2;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T02_TimerOn
VAR_INPUT
    IN : BOOL;
    PT : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    ET : TIME;
END_VAR
VAR
    timer : TON;
END_VAR
timer(IN := IN, PT := PT, Q => Q, ET => ET);
END_FUNCTION_BLOCK

FUNCTION_BLOCK T03_SR_Latch
VAR_INPUT
    S1 : BOOL;
    R : BOOL;
END_VAR
VAR_OUTPUT
    Q1 : BOOL;
END_VAR
IF S1 THEN
    Q1 := TRUE;
ELSIF R THEN
    Q1 := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T04_UpCounter
VAR_INPUT
CU : BOOL;
RESET : BOOL;
PV : INT;
END_VAR
VAR_OUTPUT
Q : BOOL;
CV : INT;
END_VAR
VAR
last_CU : BOOL;
END_VAR
IF RESET THEN
CV := 0;
ELSIF CU AND NOT last_CU THEN
CV := CV + 1;
END_IF;
last_CU := CU;
Q := (CV >= PV);
END_FUNCTION_BLOCK

FUNCTION_BLOCK T05_TimerOff
VAR_INPUT
    IN : BOOL;
    PT : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    ET : TIME;
END_VAR
VAR
    tof_inst : TOF;
END_VAR
    tof_inst(IN := IN, PT := PT, Q => Q, ET => ET);
END_FUNCTION_BLOCK

FUNCTION_BLOCK T06_TempConv
VAR_INPUT
    TempC : REAL;
END_VAR
VAR_OUTPUT
    TempF : REAL;
END_VAR
TempF := (TempC * 1.8) + 32.0;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T07_Blinker
VAR_INPUT
    ENABLE : BOOL;
END_VAR
VAR_OUTPUT
    OUT : BOOL;
END_VAR
VAR
    timer : TON;
END_VAR
timer(IN := NOT timer.Q AND ENABLE, PT := T#500ms);
IF timer.Q THEN
    OUT := NOT OUT;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T08_Compare
VAR_INPUT
    VAL1 : INT;
    VAL2 : INT;
END_VAR
VAR_OUTPUT
    RESULT : BOOL;
END_VAR
RESULT := VAL1 > VAL2;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T09_Hysteresis
VAR_INPUT
    Val : REAL;
    High : REAL;
    Low : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
IF Val >= High THEN
    Q := TRUE;
ELSIF Val <= Low THEN
    Q := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T10_Absolute
VAR_INPUT
    InputVal : INT;
END_VAR
VAR_OUTPUT
    AbsVal : INT;
END_VAR
IF InputVal < 0 THEN
    AbsVal := -InputVal;
ELSE
    AbsVal := InputVal;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T11_StarDelta
VAR_INPUT
START : BOOL;
STOP : BOOL;
END_VAR
VAR_OUTPUT
Main : BOOL;
Star : BOOL;
Delta : BOOL;
END_VAR
VAR
timer : TON;
Running : BOOL;
END_VAR
IF START THEN Running := TRUE; END_IF;
IF STOP THEN Running := FALSE; END_IF;
Main := Running;
timer(IN := Running, PT := T#5s);
Star := Running AND NOT timer.Q;
Delta := Running AND timer.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T12_DOL
VAR_INPUT
    START : BOOL;
    STOP : BOOL;
    OVERLOAD : BOOL;
END_VAR
VAR_OUTPUT
    RUN : BOOL;
    FAULT : BOOL;
END_VAR
    IF OVERLOAD THEN
        FAULT := TRUE;
    END_IF;
    IF STOP THEN
        FAULT := FALSE;
    END_IF;
    IF (START OR RUN) AND NOT STOP AND NOT FAULT THEN
        RUN := TRUE;
    ELSE
        RUN := FALSE;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T13_Clamp
VAR_INPUT
IN : REAL;
MinL : REAL;
MaxL : REAL;
END_VAR
VAR_OUTPUT
OUT : REAL;
END_VAR
IF IN < MinL THEN
OUT := MinL;
ELSIF IN > MaxL THEN
OUT := MaxL;
ELSE
OUT := IN;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T14_Sorter
VAR_INPUT
    ConveyorRun : BOOL;
    PhotoIn : BOOL;
    SizeHigh : BOOL;
END_VAR
VAR_OUTPUT
    Diverter : BOOL;
    CountPass : INT;
    CountDivert : INT;
END_VAR
VAR
    last_PhotoIn : BOOL;
END_VAR
    IF NOT ConveyorRun THEN
        Diverter := FALSE;
    ELSIF PhotoIn AND NOT last_PhotoIn THEN
        IF SizeHigh THEN
            Diverter := TRUE;
            CountDivert := CountDivert + 1;
        ELSE
            Diverter := FALSE;
            CountPass := CountPass + 1;
        END_IF;
    END_IF;
    last_PhotoIn := PhotoIn;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T15_LeadLag
VAR_INPUT
    Demand : BOOL;
    Swap : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    LeadPump1 : BOOL := TRUE;
END_VAR
IF Swap THEN LeadPump1 := NOT LeadPump1; END_IF;
IF Demand THEN
    Pump1 := LeadPump1;
    Pump2 := NOT LeadPump1;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T16_Traffic
VAR_OUTPUT
    G : BOOL;
    Y : BOOL;
    R : BOOL;
END_VAR
VAR
    Phase : INT;
    Timer : TON;
END_VAR
CASE Phase OF
    0: G := TRUE; Y := FALSE; R := FALSE; Timer(IN := TRUE, PT := T#10s);
       IF Timer.Q THEN Phase := 1; Timer(IN := FALSE); END_IF;
    1: G := FALSE; Y := TRUE; R := FALSE; Timer(IN := TRUE, PT := T#3s);
       IF Timer.Q THEN Phase := 2; Timer(IN := FALSE); END_IF;
    2: G := FALSE; Y := FALSE; R := TRUE; Timer(IN := TRUE, PT := T#13s);
       IF Timer.Q THEN Phase := 0; Timer(IN := FALSE); END_IF;
END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T17_Debounce
VAR_INPUT
RawIn : BOOL;
END_VAR
VAR_OUTPUT
FilteredOut : BOOL;
END_VAR
VAR
T_On : TON;
T_Off : TOF;
END_VAR
T_On(IN := RawIn, PT := T#50ms);
T_Off(IN := T_On.Q, PT := T#50ms);
FilteredOut := T_Off.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T18_FillStation
VAR_INPUT
    Start : BOOL;
    BottleDetected : BOOL;
    FullSignal : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
    FillValve : BOOL;
END_VAR
VAR
    State : INT; (* 0: Idle, 1: Feeding, 2: Filling, 3: Discharge *)
END_VAR
    CASE State OF
        0: Conveyor := FALSE; FillValve := FALSE;
           IF Start THEN State := 1; END_IF;
        1: Conveyor := TRUE; FillValve := FALSE;
           IF BottleDetected THEN State := 2; END_IF;
        2: Conveyor := FALSE; FillValve := TRUE;
           IF FullSignal THEN State := 3; END_IF;
        3: Conveyor := TRUE; FillValve := FALSE;
           IF NOT BottleDetected THEN State := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T19_Average
VAR_INPUT
    NewVal : REAL;
END_VAR
VAR_OUTPUT
    Avg : REAL;
END_VAR
VAR
    Buf : ARRAY[0..2] OF REAL;
END_VAR
Buf[2] := Buf[1];
Buf[1] := Buf[0];
Buf[0] := NewVal;
Avg := (Buf[0] + Buf[1] + Buf[2]) / 3.0;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T20_Ramp
VAR_INPUT
    Setpoint : REAL;
    Rate : REAL;
END_VAR
VAR_IN_OUT
    Out : REAL;
END_VAR
IF Out < Setpoint THEN
    Out := Out + Rate;
    IF Out > Setpoint THEN Out := Setpoint; END_IF;
ELSIF Out > Setpoint THEN
    Out := Out - Rate;
    IF Out < Setpoint THEN Out := Setpoint; END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T21_Batch
VAR_INPUT
    Start, LevelFull, LevelEmpty : BOOL;
END_VAR
VAR_OUTPUT
    FillValve, Motor, DrainValve : BOOL;
END_VAR
VAR
    State : INT; (* 0: Idle, 1: Fill, 2: Mix, 3: Drain *)
    MixTimer : TON;
END_VAR
CASE State OF
    0: IF Start THEN State := 1; END_IF;
    1: FillValve := TRUE; IF LevelFull THEN State := 2; FillValve := FALSE; END_IF;
    2: Motor := TRUE; MixTimer(IN := TRUE, PT := T#10s);
       IF MixTimer.Q THEN State := 3; Motor := FALSE; MixTimer(IN := FALSE); END_IF;
    3: DrainValve := TRUE; IF LevelEmpty THEN State := 0; DrainValve := FALSE; END_IF;
END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T22_PID
VAR_INPUT
    PV, SP, Kp, Ki, Kd : REAL;
END_VAR
VAR_OUTPUT
    Out : REAL;
END_VAR
VAR
    Error, LastError, IntAccum, Deriv : REAL;
END_VAR
    Error := SP - PV;
    IntAccum := IntAccum + Error;
    Deriv := Error - LastError;
    Out := (Kp * Error) + (Ki * IntAccum) + (Kd * Deriv);
    LastError := Error;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T23_ArrayMax
VAR_INPUT
    Vals : ARRAY[0..9] OF INT;
END_VAR
VAR_OUTPUT
    MaxVal : INT;
END_VAR
VAR
    i : INT;
END_VAR
MaxVal := Vals[0];
FOR i := 1 TO 9 DO
    IF Vals[i] > MaxVal THEN
        MaxVal := Vals[i];
    END_IF;
END_FOR;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T24_Alarm
VAR_INPUT
    Fault : BOOL;
    Ack : BOOL;
END_VAR
VAR_OUTPUT
    AlarmActive : BOOL;
END_VAR
VAR
    Latched : BOOL;
END_VAR
IF Fault THEN Latched := TRUE; END_IF;
IF Ack AND NOT Fault THEN Latched := FALSE; END_IF;
AlarmActive := Latched;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T25_CRC8
VAR_INPUT
    Data : ARRAY[0..3] OF BYTE;
END_VAR
VAR_OUTPUT
    CRC : BYTE;
END_VAR
VAR
    i : INT;
END_VAR
CRC := 16#FF;
FOR i := 0 TO 3 DO
    CRC := CRC XOR Data[i];
END_FOR;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T26_Interpolate
VAR_INPUT
    X, X1, Y1, X2, Y2 : REAL;
END_VAR
VAR_OUTPUT
    Y : REAL;
END_VAR
IF (X2 - X1) <> 0.0 THEN
    Y := Y1 + (X - X1) * (Y2 - Y1) / (X2 - X1);
ELSE
    Y := Y1;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T27_Sort
VAR_IN_OUT
    Arr : ARRAY[0..4] OF INT;
END_VAR
VAR
    i, j, Temp : INT;
END_VAR
FOR i := 0 TO 3 DO
    FOR j := 0 TO 3 - i DO
        IF Arr[j] > Arr[j+1] THEN
            Temp := Arr[j];
            Arr[j] := Arr[j+1];
            Arr[j+1] := Temp;
        END_IF;
    END_FOR;
END_FOR;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T28_Freq
VAR_INPUT
    Pulse : BOOL;
END_VAR
VAR_OUTPUT
    Freq : REAL;
END_VAR
VAR
    Count : INT;
    LastPulse : BOOL;
    Timer : TON;
END_VAR
IF Pulse AND NOT LastPulse THEN Count := Count + 1; END_IF;
LastPulse := Pulse;
Timer(IN := TRUE, PT := T#1s);
IF Timer.Q THEN
    Freq := INT_TO_REAL(Count);
    Count := 0;
    Timer(IN := FALSE);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK T29_ModbusPack
VAR_INPUT
    Val1, Val2 : INT;
END_VAR
VAR_OUTPUT
    Payload : ARRAY[0..3] OF BYTE;
END_VAR
VAR
    W1, W2 : WORD;
END_VAR
    W1 := INT_TO_WORD(Val1);
    W2 := INT_TO_WORD(Val2);
    Payload[0] := WORD_TO_BYTE(SHR(W1, 8));
    Payload[1] := WORD_TO_BYTE(W1 AND 16#00FF);
    Payload[2] := WORD_TO_BYTE(SHR(W2, 8));
    Payload[3] := WORD_TO_BYTE(W2 AND 16#00FF);
END_FUNCTION_BLOCK

FUNCTION_BLOCK T30_Elevator
VAR_INPUT
CallFloor : INT;
AtFloor : INT;
END_VAR
VAR_OUTPUT
MotorUp : BOOL;
MotorDown : BOOL;
END_VAR
IF CallFloor > AtFloor THEN
MotorUp := TRUE;
MotorDown := FALSE;
ELSIF CallFloor < AtFloor THEN
MotorUp := FALSE;
MotorDown := TRUE;
ELSE
MotorUp := FALSE;
MotorDown := FALSE;
END_IF;
END_FUNCTION_BLOCK
